focus<-fread(file.path(OUT,'00_input_audit/candidate_overlap.csv'))$gene;cr<-fread(file.path(OUT,'05_LLPS_ligand_correlation/cell_and_specimen_correlations.csv.gz'));pr<-fread(file.path(OUT,'05_LLPS_ligand_correlation/patient_effect_tests.csv.gz'));pb<-fread(file.path(OUT,'05_LLPS_ligand_correlation/pseudobulk_continuous_associations.csv.gz'));cc<-cr[sensitivity=='original'&scope=='pooled_tumor'&gene%in%focus];corrows<-list(cc[,.(gene,metric='Cell Pearson\n(descriptive)',r=pearson)],cc[,.(gene,metric='Cell Spearman\n(descriptive)',r=spearman)],pr[sensitivity=='original'&stratum=='ALL'&metric=='adjusted_r'&gene%in%focus,.(gene,metric='Within-specimen adjusted\n(patient median)',r=median)],pb[min_cells==10&score_type=='score_mean'&stratum=='ALL'&gene%in%focus,.(gene,metric='Patient Pearson',r=pearson)],pb[min_cells==10&score_type=='score_mean'&stratum=='ALL'&gene%in%focus,.(gene,metric='Patient Spearman',r=spearman)],pb[min_cells==10&score_type=='score_mean'&startsWith(stratum,'dataset:')&gene%in%focus,.(gene,metric=paste('Patient',sub('dataset:','',stratum)),r=spearman)]);z<-rbindlist(corrows);z[,metric:=factor(metric,levels=unique(metric))];p<-ggplot(z,aes(metric,factor(gene,levels=rev(focus)),fill=r))+geom_tile(color='white',linewidth=.4)+scale_fill_gradient2(low='#2166AC',mid='white',high='#B2182B',limits=c(-1,1),na.value='grey85',guide=guide_colourbar(display='rectangles'))+jin_theme()+theme(axis.text.x=element_text(angle=35,hjust=1))+labs(x=NULL,y=NULL,fill='Correlation');exp(p,'LLPS_ligand_correlation_heatmap',z,12,9)
ex<-readRDS(file.path(OUT,'00_input_audit/C5_expression_small.rds'));md<-ex$metadata;pd<-fread(file.path(OUT,'05_LLPS_ligand_correlation/patient_pseudobulk_metadata.csv'));pe<-fread(file.path(OUT,'05_LLPS_ligand_correlation/pseudobulk_ligand_expression.csv.gz'))[min_cells==10];extra<-pb[min_cells==10&stratum=='ALL'&score_type=='score_mean'&adjusted_p_FDR_focus<.05&gene%in%focus&!gene%in%c('POSTN','INHBA','FN1','TGFB1','ANGPTL4','COL1A1')][order(adjusted_p_FDR_focus),head(gene,2)];sg<-unique(c('POSTN','INHBA','FN1','TGFB1','ANGPTL4',extra));dcols<-jin_palette(sort(unique(md$dataset)));for(g in sg){z<-copy(md[clinical_group!='Normal']);z[,expression:=as.numeric(ex$data[g,match(cell,md$cell)])];p<-ggplot(z,aes(LLPS77_AUC,expression,color=dataset))+geom_point(alpha=.25,size=1)+geom_smooth(aes(group=1),method='loess',se=FALSE,color='black',linewidth=.4)+scale_color_manual(values=dcols)+jin_theme()+labs(x='LLPS score',y=paste(g,'normalized expression'),color='Dataset');exp(p,paste0('ligand_',g,'_cell_scatter'),z[,.(cell,specimen_id,patient_id,dataset,LLPS77_AUC,expression)],7,5)
 z<-merge(pe[gene==g],pd,by='patient_id');ss<-pb[gene==g&min_cells==10&stratum=='ALL'&score_type=='score_mean'];label<-sprintf('n=%d; Pearson r=%.2f; Spearman rho=%.2f\nDataset-adjusted P=%.3g; focused FDR=%.3g',ss$n_patients,ss$pearson,ss$spearman,ss$adjusted_p,ss$adjusted_p_FDR_focus);p<-ggplot(z,aes(score_mean,logCPM,color=dataset))+geom_point(size=2.5)+geom_smooth(aes(group=1),method='lm',se=FALSE,color='black',linewidth=.4)+scale_color_manual(values=dcols)+jin_theme()+labs(x='Patient mean LLPS score',y=paste(g,'TMM logCPM'),color='Dataset',subtitle=label)+theme(plot.subtitle=element_text(family='Arial',size=11));exp(p,paste0('ligand_',g,'_patient_scatter'),z,8,5)
