# Technical covariate paired QC, using the same primary eligible tumor specimens.
tc<-fread(file.path(OUT,'01_LLPS_stratification/highlow_technical_covariates.csv'))[method=='within_median'&clinical_group!='Normal'];eligible<-fread(file.path(OUT,'01_LLPS_stratification/specimen_eligibility.csv'))[method=='within_median'&min_cells==10&eligible==TRUE&clinical_group!='Normal',specimen_id];tc<-tc[specimen_id%in%eligible];tc<-tc[,.(nCount_mean=median(nCount_mean),nFeature_mean=median(nFeature_mean)),by=.(patient_id,dataset,state)];tt<-melt(tc,id.vars=c('patient_id','dataset','state'),variable.name='metric',value.name='value');tt[,state:=factor(state,levels=c('low','high'))];p<-ggplot(tt,aes(state,value,group=patient_id,color=dataset))+geom_line(linewidth=.4,alpha=.7)+geom_point(size=2)+scale_color_manual(values=dcols)+facet_wrap(~metric,scales='free_y')+jin_theme()+labs(x=NULL,y='Patient mean technical covariate',color='Dataset');exp(p,'technical_covariate_paired_QC',tt,10,5)

